import {parseCSV,analyze,demoRows,seal,verify,fetchNASA} from './core.mjs';
const $=id=>document.getElementById(id);let rows=[],source=null,bundle=null,busy=false;
function notice(message,error=false){$('notice').hidden=false;$('notice').textContent=message;$('notice').className='notice'+(error?' error':'');}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function escape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function resetEvidence() {bundle=null;$('root').value='';$('export').disabled=true;$('verify').disabled=true;$('tamper').disabled=true;$('seal-state').textContent='Dataset changed. Seal it to preserve the current evidence.';$('verification').replaceChildren();}
function load(data,origin){rows=data;source=origin;resetEvidence();$('seal').disabled=false;render();}
function render(){const findings=analyze(rows);const flagged=findings.filter(r=>r.status==='review');$('readings').textContent=rows.length;$('flagged').textContent=flagged.length;$('mean').textContent=(rows.reduce((s,r)=>s+r.value,0)/rows.length).toFixed(1)+' °C';$('coverage').textContent=Math.round(findings.filter(r=>r.status!=='warmup').length/rows.length*100)+'%';$('source-badge').textContent=source.kind.toUpperCase();$('source-badge').className='badge '+(source.kind==='Synthetic demo'?'demo':'real');$('source-details').textContent=source.note||source.name||source.kind;
 const visible=$('only-flags').checked?flagged:findings;$('rows').innerHTML=visible.length?visible.map(r=>`<tr><td>${escape(r.date)}</td><td><strong>${r.value.toFixed(1)} °C</strong></td><td>${r.baseline===null?'—':r.baseline.toFixed(1)+' °C'}</td><td><span class="status ${r.status}">${r.status==='review'?'Needs review':r.status==='warmup'?'Baseline':'In range'}</span></td><td>${escape(r.reason)}</td></tr>`).join(''):'<tr><td colspan="5" class="table-empty">No readings flagged. Switch off “Only flagged readings” to inspect the complete dataset.</td></tr>';
 const w=800,h=285,left=46,right=18,top=20,bottom=36;const vals=findings.flatMap(r=>r.baseline===null?[r.value]:[r.value,r.baseline]);const lo=Math.floor(Math.min(...vals)-2),hi=Math.ceil(Math.max(...vals)+2);const x=i=>left+i*(w-left-right)/(rows.length-1),y=v=>h-bottom-(v-lo)*(h-top-bottom)/(hi-lo);
 const path=rs=>rs.map((r,i)=>`${i?'L':'M'} ${x(r.i).toFixed(1)} ${y(r.v).toFixed(1)}`).join(' ');const observed=path(rows.map((r,i)=>({i,v:r.value})));const baseline=path(findings.map((r,i)=>({i,v:r.baseline})).filter(r=>r.v!==null));
 const grid=Array.from({length:5},(_,i)=>{const v=lo+(hi-lo)*i/4;return `<line x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}" stroke="#e7eef1"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end" fill="#728792" font-size="12">${v.toFixed(0)}°</text>`;}).join('');
 const marks=findings.map((r,i)=>r.status==='review'?`<circle cx="${x(i)}" cy="${y(r.value)}" r="6" fill="#cf473e" stroke="white" stroke-width="2"><title>${escape(r.date)}: ${r.value} °C — ${escape(r.reason)}</title></circle>`:'').join('');
 $('chart').className='';$('chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Temperature timeline with ${rows.length} readings and ${flagged.length} flagged outliers"><title>Recorded temperatures and historical baseline</title>${grid}<path d="${baseline}" stroke="#93aeb7" fill="none" stroke-width="2" stroke-dasharray="6 4"/><path d="${observed}" fill="none" stroke="#007f77" stroke-width="2.5" stroke-linejoin="round"/>${marks}<text x="${left}" y="${h-8}" fill="#728792" font-size="12">${rows[0].date}</text><text x="${w-right}" y="${h-8}" text-anchor="end" fill="#728792" font-size="12">${rows.at(-1).date}</text></svg>`;
}
async function action(fn){if(busy)return;busy=true;try{await fn();}catch(e){notice(e.message,true);}finally{busy=false;}}
$('demo').onclick=()=>{if(busy)return;load(demoRows(),{kind:'Synthetic demo',note:'Synthetic daily temperatures, 1 Sep–15 Oct 2026. Outlier inserted on 29 Sep for demonstration.'});notice('Demo loaded. One unusual reading is waiting for review.');};
$('csv-file').onchange=e=>action(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>500000)throw Error('CSV must be smaller than 500 KB.');const parsed=parseCSV(await f.text());load(parsed,{kind:'CSV upload',name:f.name,note:`Local CSV: ${f.name}. Uploaded values are not independently certified.`});notice(`Imported ${parsed.length} readings. Your CSV stays in this browser.`);});
$('template').onclick=()=>download('traceclimate-template.csv','date,value\n'+demoRows().map(r=>`${r.date},${r.value}`).join('\n'),'text/csv');
$('fetch-nasa').onclick=()=>action(async()=>{const button=$('fetch-nasa');button.disabled=true;button.textContent='Contacting NASA…';try{const result=await fetchNASA(Number($('lat').value),Number($('lon').value),$('start').value,$('end').value);load(result.rows,result.source);notice(`Imported ${rows.length} real NASA POWER readings.`);}finally{button.disabled=false;button.textContent='Import NASA data';}});
$('only-flags').onchange=()=>{if(rows.length)render();};
$('seal').onclick=()=>action(async()=>{const button=$('seal');button.disabled=true;try{bundle=await seal(rows,source);$('root').value=bundle.root;$('seal-state').textContent=`Sealed ${rows.length} records. Export the bundle and save the root separately.`;$('export').disabled=false;$('verify').disabled=false;$('tamper').disabled=false;notice('Evidence sealed. No data was sent to a server.');}finally{button.disabled=false;}});
$('export').onclick=()=>{if(bundle)download('traceclimate-evidence.json',JSON.stringify(bundle,null,2),'application/json');};
async function showVerify(candidate){const result=await verify(candidate,$('root').value.trim());$('verification').className='verification'+(result.valid?'':' error');$('verification').textContent=result.valid?`Integrity verified · ${result.count} records match your saved root. Integrity is not proof of measurement accuracy.`:`Tampering detected · record ${(result.index??0)+1}. ${result.reason}`;return result;}
$('verify').onclick=()=>action(()=>showVerify(bundle));
$('tamper').onclick=()=>action(async()=>{const copy=structuredClone(bundle);copy.blocks[Math.min(10,copy.blocks.length-1)].reading.value+=10;await showVerify(copy);notice('Changed one reading in a temporary copy. Your original evidence remains intact.');});
$('evidence-file').onchange=e=>action(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>4000000)throw Error('Evidence must be smaller than 4 MB.');const candidate=JSON.parse(await f.text());if(candidate?.header?.schema!=='traceclimate-evidence-v1'||!Array.isArray(candidate.blocks)||candidate.blocks.length>2000)throw Error('This is not a TraceClimate evidence bundle.');bundle=candidate;$('verify').disabled=false;$('tamper').disabled=false;$('export').disabled=false;$('seal-state').textContent='Evidence opened. Paste the independently saved root, then verify. The embedded root is not automatically trusted.';notice('Evidence ready for verification. Your analysis dataset has not changed.');});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'get_climate_analysis',description:'Read current dataset summary and flagged readings without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({source,count:rows.length,flagged:analyze(rows).filter(r=>r.status==='review')})});}catch{/* Browsers without WebMCP still expose the full interface. */}}
